CREATE TABLE after_sale(id BIGINT PRIMARY KEY AUTO_INCREMENT,after_sale_no VARCHAR(64) NOT NULL UNIQUE,order_no VARCHAR(64) NOT NULL,member_id BIGINT NOT NULL,type VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,reason VARCHAR(255) NOT NULL,return_carrier VARCHAR(64) NULL,return_tracking_no VARCHAR(100) NULL,return_received BOOLEAN NOT NULL DEFAULT FALSE,accepted_at DATETIME(6) NULL,refund_no VARCHAR(64) NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(order_no) REFERENCES trade_order(order_no),INDEX idx_after_sale_member(member_id,id),INDEX idx_after_sale_status(status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE after_sale_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,after_sale_no VARCHAR(64) NOT NULL,action VARCHAR(32) NOT NULL,actor_type VARCHAR(16) NOT NULL,actor_id BIGINT NULL,reason VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(after_sale_no) REFERENCES after_sale(after_sale_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
